500.source:
[System println: "CASE integer-loop"];
[Module load: #time];
[[|

let operation := [| [1 to: 500 do: [:i | nil]]];
let result := [operation value];
[[result = 1] ifFalse: [| [System println: "PERF_BAD"]]];
[1 to: 3 do: [:sample |
  [System gc];
  let startedCpu := [16 clockNanos]; let startedWall := [6 clockNanos];
  [operation value];
  let endedWall := [6 clockNanos]; let endedCpu := [16 clockNanos];
  [System println: [endedCpu - startedCpu]];
  [System println: [endedWall - startedWall]]
]];
[System println: "PERF_OK"]
] value]

[System println: "CASE range-loop"];
[Module load: #time];
[[|
let range := [1 to: 500];
let operation := [| [range do: [:i | nil]]];
let result := [operation value];
[[result == range] ifFalse: [| [System println: "PERF_BAD"]]];
[1 to: 3 do: [:sample |
  [System gc];
  let startedCpu := [16 clockNanos]; let startedWall := [6 clockNanos];
  [operation value];
  let endedWall := [6 clockNanos]; let endedCpu := [16 clockNanos];
  [System println: [endedCpu - startedCpu]];
  [System println: [endedWall - startedWall]]
]];
[System println: "PERF_OK"]
] value]

[System println: "CASE method-loop"];
[Module load: #time];
[[|
let target := [Object clone]; [Reflect defineMethod: #perfEcho: on: target as: [:self :argument | argument]];
let operation := [| [1 to: 500 do: [:i | [target perfEcho: i]]]];
let result := [operation value];
[[result = 1] ifFalse: [| [System println: "PERF_BAD"]]];
[1 to: 3 do: [:sample |
  [System gc];
  let startedCpu := [16 clockNanos]; let startedWall := [6 clockNanos];
  [operation value];
  let endedWall := [6 clockNanos]; let endedCpu := [16 clockNanos];
  [System println: [endedCpu - startedCpu]];
  [System println: [endedWall - startedWall]]
]];
[System println: "PERF_OK"]
] value]

[Globals at: #LogueBenchConfig put: {#phase -> "arena" #seed -> 12345 #width -> 16 #monsters -> 0 #turns -> 16 #batches -> 4 #samples -> 1 #allocation -> false #replace -> false}];
[System load: "logue-bench.birnam"];

